"""Interval merging utilities."""


def merge_intervals(intervals):
    """Merge overlapping and touching [start, end] intervals.

    Args:
        intervals: iterable of (start, end) integer pairs.

    Returns:
        New list of merged pairs, sorted by start.

    Raises:
        ValueError: if any pair is reversed (start > end) or not a pair
            of two integers.
        TypeError: if an entry is not a pair.
    """
    normalized = []
    for entry in intervals:
        try:
            start, end = entry
        except (TypeError, ValueError):
            raise TypeError(f"interval must be a pair, got {entry!r}") from None
        if not isinstance(start, int) or not isinstance(end, int):
            raise TypeError(
                f"interval bounds must be integers, got {entry!r}"
            )
        if start > end:
            raise ValueError(f"reversed interval: start {start} > end {end}")
        normalized.append((start, end))

    normalized.sort()

    merged = []
    for start, end in normalized:
        # touching counts: merged[-1][1] + 1 > start  =>  merged[-1][1] >= start
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged

