"""Tests for merge_intervals."""

import unittest

from solution import merge_intervals


class TestMergeIntervals(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single(self):
        self.assertEqual(merge_intervals([(1, 3)]), [(1, 3)])

    def test_overlap(self):
        self.assertEqual(
            merge_intervals([(1, 3), (2, 6), (8, 10)]),
            [(1, 6), (8, 10)],
        )

    def test_touching_endpoints_merge(self):
        self.assertEqual(
            merge_intervals([(1, 2), (2, 3)]),
            [(1, 3)],
        )
        self.assertEqual(
            merge_intervals([(1, 5), (5, 9), (9, 10)]),
            [(1, 10)],
        )

    def test_touching_negative(self):
        self.assertEqual(
            merge_intervals([(-3, -1), (-1, 0)]),
            [(-3, 0)],
        )

    def test_disjoint_stays_separate(self):
        self.assertEqual(
            merge_intervals([(1, 2), (3, 4)]),
            [(1, 2), (3, 4)],
        )

    def test_unsorted_input_output_sorted(self):
        self.assertEqual(
            merge_intervals([(8, 10), (1, 3), (2, 6)]),
            [(1, 6), (8, 10)],
        )

    def test_contained_interval_absorbed(self):
        self.assertEqual(
            merge_intervals([(1, 10), (2, 3), (4, 5)]),
            [(1, 10)],
        )

    def test_zero_width_interval(self):
        self.assertEqual(
            merge_intervals([(5, 5)]),
            [(5, 5)],
        )
        # zero-width point inside another interval
        self.assertEqual(
            merge_intervals([(1, 3), (2, 2)]),
            [(1, 3)],
        )
        # zero-width point touching an interval
        self.assertEqual(
            merge_intervals([(1, 3), (3, 3)]),
            [(1, 3)],
        )

    def test_duplicates(self):
        self.assertEqual(
            merge_intervals([(1, 1), (1, 1)]),
            [(1, 1)],
        )

    def test_does_not_mutate_input(self):
        original = [(5, 6), (1, 3), (2, 4)]
        snapshot = list(original)
        merge_intervals(original)
        self.assertEqual(original, snapshot)

    def test_reversed_raises_value_error(self):
        with self.assertRaises(ValueError):
            merge_intervals([(3, 1)])
        with self.assertRaises(ValueError):
            merge_intervals([(1, 2), (4, 3)])

    def test_reversed_checked_before_merge(self):
        # reversed pair must raise even if other pairs overlap
        with self.assertRaises(ValueError):
            merge_intervals([(1, 5), (9, 7)])

    def test_accepts_lists_and_tuples(self):
        self.assertEqual(
            merge_intervals([[1, 3], (2, 4)]),
            [(1, 4)],
        )

    def test_generator_input(self):
        self.assertEqual(
            merge_intervals(iter([(1, 3), (3, 5)])),
            [(1, 5)],
        )

    def test_result_is_new_object(self):
        result = merge_intervals([(1, 3)])
        self.assertIsNot(result, [(1, 3)])


if __name__ == "__main__":
    unittest.main(verbosity=2)
